# Harr component installation and version status.

readonly HARR_LEANCTX_VERSION="3.11.0"
readonly HARR_LEANCTX_BUILD="3.11.0-harr-unified.7"
readonly HARR_LEANCTX_ID="harr-v3.11.0-unified.7@4fe3b6b884ee"
readonly HARR_LEANCTX_RELEASE_TAG="harr-v3.11.0-unified.7"
readonly HARR_LEANCTX_REPO="smollgreymouse/lean-ctx"

write_runtime_env() {
  local node_bin="$1"
  local node_bin_dir
  node_bin_dir="$(cd -- "$(dirname -- "$node_bin")" && pwd)"

  ensure_private_dir "$HARR_CONFIG_DIR"
  cat >"$HARR_RUNTIME_ENV" <<EOF_RUNTIME
# Managed by Harr. Regenerated by: harr install mcp
HARR_NODE_BIN_DIR=${node_bin_dir}
HARR_NPM_BIN_DIR=${HARR_NPM_BIN_DIR}
EOF_RUNTIME
  chmod 0600 "$HARR_RUNTIME_ENV"
}

check_node_runtime() {
  require_command node
  require_command npm

  local node_bin major
  node_bin="$(command -v node)"
  major="$(node -p 'Number(process.versions.node.split(".")[0])')"
  [[ "$major" =~ ^[0-9]+$ ]] || die 'could not determine Node.js major version'
  ((major >= 20 && major < 25)) || die "Node.js 20-24 is required by the Harr MCP runtime; current: $(node --version)"
  printf '%s\n' "$node_bin"
}

install_node_mcp_stack() {
  local node_bin package_file
  node_bin="$(check_node_runtime)"

  install -d -m 0755 "$HARR_NPM_PREFIX"
  package_file="${HARR_NPM_PREFIX}/package.json"
  mcp_manager npm-package-json >"$package_file"

  printf 'Installing selected Harr npm MCP runtimes...\n'
  PATH="$(dirname -- "$node_bin"):${PATH}" \
    npm install \
      --prefix "$HARR_NPM_PREFIX" \
      --omit=dev \
      --no-audit \
      --no-fund \
      --package-lock=false

  write_runtime_env "$node_bin"
}

prefetch_mcp_runtimes() {
  mcp_manager prefetch-runtimes
}

leanctx_target() {
  local arch libc glibc_ver major minor
  arch="$(uname -m)"
  case "$arch" in
    x86_64) arch=x86_64 ;;
    arm64|aarch64) arch=aarch64 ;;
    *) die "unsupported LeanCTX architecture: $arch" ;;
  esac

  libc=musl
  if command -v ldd >/dev/null 2>&1; then
    glibc_ver="$(ldd --version 2>&1 | head -1 | grep -oE '[0-9]+\.[0-9]+$' || true)"
    if [[ -n "$glibc_ver" ]]; then
      major="${glibc_ver%%.*}"
      minor="${glibc_ver##*.}"
      if ((major > 2 || (major == 2 && minor >= 35))); then libc=gnu; fi
    fi
  fi
  printf '%s\n' "${arch}-unknown-linux-${libc}"
}

verify_sha256() {
  local file="$1" expected="$2" actual
  if command -v sha256sum >/dev/null 2>&1; then actual="$(sha256sum "$file" | awk '{print $1}')";
  elif command -v shasum >/dev/null 2>&1; then actual="$(shasum -a 256 "$file" | awk '{print $1}')";
  else die 'sha256sum or shasum is required to install LeanCTX'; fi
  [[ "$actual" == "$expected" ]] || die "LeanCTX checksum mismatch: expected $expected, got $actual"
}

package_linux_dir() {
  [[ "${HARR_INSTALL_TYPE:-source}" == package ]] || return 1
  (cd -- "${CLI_LIB_DIR}/../.." && pwd)
}

package_leanctx_binary() {
  local linux_dir
  linux_dir="$(package_linux_dir)" || return 1
  printf '%s/vendor/lean-ctx/lean-ctx\n' "$linux_dir"
}

package_mcp_manager() {
  local linux_dir package_root
  linux_dir="$(package_linux_dir)" || return 1
  package_root="$(cd -- "${linux_dir}/.." && pwd)"
  printf '%s/common/mcp/manager.py\n' "$package_root"
}

leanctx_real_binary() {
  if [[ "${HARR_INSTALL_TYPE:-source}" == package ]]; then
    package_leanctx_binary
  else
    printf '%s/lean-ctx/%s/lean-ctx\n' "$HARR_VENDOR_DIR" "$HARR_LEANCTX_BUILD"
  fi
}

leanctx_wrapper_source() {
  if [[ "${HARR_INSTALL_TYPE:-source}" == package ]]; then
    local linux_dir
    linux_dir="$(package_linux_dir)" || return 1
    printf '%s/files/leanctx/lean-ctx-wrapper\n' "$linux_dir"
  else
    printf '%s/../leanctx/lean-ctx-wrapper\n' "$CLI_LIB_DIR"
  fi
}

install_leanctx_wrapper() {
  local wrapper_src target backup_dir
  wrapper_src="$(leanctx_wrapper_source)"
  target="${HOME}/.local/bin/lean-ctx"
  backup_dir="${HARR_LIBEXEC_DIR}/backup"

  [[ -x "$wrapper_src" ]] || die "LeanCTX wrapper missing: $wrapper_src"
  install -d -m 0755 "${HOME}/.local/bin" "$backup_dir"

  if [[ -e "$target" ]] && ! grep -q 'HARR_LEANCTX_WRAPPER=1' "$target" 2>/dev/null; then
    if [[ ! -e "${backup_dir}/lean-ctx.pre-harr" ]]; then
      cp -a "$target" "${backup_dir}/lean-ctx.pre-harr"
      printf 'Backed up previous lean-ctx launcher to %s\n' "${backup_dir}/lean-ctx.pre-harr"
    fi
  fi

  if [[ "${HARR_INSTALL_TYPE:-source}" == package ]]; then
    local real manager content tmp
    real="$(package_leanctx_binary)"
    manager="$(package_mcp_manager)"
    printf -v content '#!/usr/bin/env bash\n# HARR_LEANCTX_WRAPPER=1\n# HARR_PACKAGE_LEANCTX_LAUNCHER=1\nset -Eeuo pipefail\nif [[ "${1:-}" == "--version" && "$#" -eq 1 ]]; then exec %q --version; fi\nexport HARR_LEANCTX_REAL=%q\nexport HARR_MCP_MANAGER=%q\nexec %q "$@"' "$real" "$real" "$manager" "$wrapper_src"
    if [[ -r "$target" && "$(cat -- "$target")" == "$content" ]]; then
      return
    fi
    tmp="${target}.tmp.$$"
    printf '%s\n' "$content" >"$tmp"
    chmod 0755 "$tmp"
    mv -f -- "$tmp" "$target"
    return
  fi

  install -m 0755 "$wrapper_src" "$target"
}

validate_package_leanctx_runtime() {
  [[ "${HARR_INSTALL_TYPE:-source}" == package ]] || return 0
  local real identity
  real="$(package_leanctx_binary)"
  [[ -x "$real" ]] || die "Packaged Harr LeanCTX binary missing: $real"
  identity="$("$real" --version 2>/dev/null || true)"
  [[ "$identity" == *"Harr build ${HARR_LEANCTX_ID},"* ]] || \
    die "Packaged Harr LeanCTX identity mismatch: expected ${HARR_LEANCTX_ID}"
}

sync_package_leanctx_runtime() {
  [[ "${HARR_INSTALL_TYPE:-source}" == package ]] || return 0
  # A bare package install must remain non-invasive until `harr setup`. During
  # upgrades, however, an already managed Harr launcher must follow the package
  # atomically on the first Harr invocation. Never replace an unrelated user
  # `lean-ctx` executable here.
  local target="${HOME}/.local/bin/lean-ctx"
  if [[ -e "$target" ]] && grep -q '^# HARR_LEANCTX_WRAPPER=1$' "$target" 2>/dev/null; then
    install_leanctx_wrapper
  fi
}

install_leanctx() {
  if [[ "${HARR_INSTALL_TYPE:-source}" == package ]]; then
    validate_package_leanctx_runtime
    install_leanctx_wrapper
    return
  fi

  require_command curl
  require_command tar

  local target version_dir real_bin tmpdir archive sums expected asset sums_url
  target="$(leanctx_target)"
  version_dir="${HARR_VENDOR_DIR}/lean-ctx/${HARR_LEANCTX_BUILD}"
  real_bin="${version_dir}/lean-ctx"

  if [[ -x "$real_bin" ]] && "$real_bin" --version 2>/dev/null | grep -Fq "Harr build ${HARR_LEANCTX_ID},"; then
    printf 'LeanCTX %s already installed in Harr vendor dir.\n' "$HARR_LEANCTX_VERSION"
    install_leanctx_wrapper
    return
  fi

  # Portable/source distributions may carry a verified LeanCTX binary next to
  # the installer. They still own a user-scoped runtime, unlike package mode.
  local bundled="${HARR_BUNDLED_LEANCTX:-}"
  if [[ -n "$bundled" && -x "$bundled" ]]; then
    "$bundled" --version | grep -Fq "Harr build ${HARR_LEANCTX_ID}," || die 'bundled LeanCTX identity mismatch'
    install -d -m 0755 "$version_dir"
    install -m 0755 "$bundled" "$real_bin"
    install_leanctx_wrapper
    return
  fi

  tmpdir="$(mktemp -d)"
  archive="${tmpdir}/lean-ctx.tar.gz"
  sums="${tmpdir}/SHA256SUMS"
  asset="https://github.com/${HARR_LEANCTX_REPO}/releases/download/${HARR_LEANCTX_RELEASE_TAG}/lean-ctx-${target}.tar.gz"
  sums_url="https://github.com/${HARR_LEANCTX_REPO}/releases/download/${HARR_LEANCTX_RELEASE_TAG}/SHA256SUMS"

  printf 'Installing LeanCTX %s (%s)...\n' "$HARR_LEANCTX_VERSION" "$target"
  curl -fsSL "$asset" -o "$archive"
  curl -fsSL "$sums_url" -o "$sums"
  expected="$(awk -v f="lean-ctx-${target}.tar.gz" '$2 == f || $2 == "*" f {print $1; exit}' "$sums")"
  [[ -n "$expected" ]] || die "checksum entry not found for lean-ctx-${target}.tar.gz"
  verify_sha256 "$archive" "$expected"

  tar -xzf "$archive" -C "$tmpdir"
  [[ -x "${tmpdir}/lean-ctx" ]] || die 'LeanCTX archive did not contain lean-ctx executable'
  install -d -m 0755 "$version_dir"
  install -m 0755 "${tmpdir}/lean-ctx" "$real_bin"
  "$real_bin" --version | grep -Fq "Harr build ${HARR_LEANCTX_ID}," || die 'installed LeanCTX build identity check failed'

  install_leanctx_wrapper
  rm -rf "$tmpdir"
}

cmd_install_components() {
  local target="${1:-all}"
  [[ $# -le 1 ]] || die 'usage: harr install [all|leanctx|mcp]'

  case "$target" in
    all) install_node_mcp_stack; prefetch_mcp_runtimes; install_leanctx; cmd_leanctx_apply ;;
    mcp) install_node_mcp_stack; prefetch_mcp_runtimes ;;
    leanctx) install_leanctx; cmd_leanctx_apply ;;
    *) die 'usage: harr install [all|leanctx|mcp]' ;;
  esac
}

cmd_components_status() {
  local lean_actual='' lean_identity='' lean_real
  lean_real="$(leanctx_real_binary)"
  if [[ -x "$lean_real" ]]; then lean_identity="$("$lean_real" --version 2>/dev/null || true)"; lean_actual="$(printf '%s\n' "$lean_identity" | grep -oE '[0-9]+\.[0-9]+\.[0-9]+' | head -1 || true)"; fi

  printf '%-16s %-18s %-16s %s\n' COMPONENT EXPECTED STATE INSTALLED
  if [[ "$lean_actual" == "$HARR_LEANCTX_VERSION" && "$lean_identity" == *"Harr build ${HARR_LEANCTX_ID},"* ]]; then printf '%-16s %-18s %-16s %s\n' leanctx "$HARR_LEANCTX_BUILD" ok "$lean_actual";
  elif [[ -n "$lean_actual" ]]; then printf '%-16s %-18s %-16s %s\n' leanctx "$HARR_LEANCTX_BUILD" version-mismatch "$lean_actual";
  else printf '%-16s %-18s %-16s %s\n' leanctx "$HARR_LEANCTX_BUILD" missing '-'; fi

  while IFS=$'\t' read -r name expected state installed; do
    printf '%-16s %-18s %-16s %s\n' "$name" "$expected" "$state" "$installed"
  done < <(mcp_manager_readonly components --npm-prefix "$HARR_NPM_PREFIX")
}
